def _escape_value(self, value):
    # This is changed from a previous version because this string is
    # being passed to the query string and query strings must
    # be url encoded. In particular STS requires the saml_response to
    # be urlencoded when calling assume_role_with_saml.
    return urllib.parse.quote(value)

def unquote_v(nv):
    if len(nv) == 1:
        return nv
    else:
        return (nv[0], urllib.parse.unquote(nv[1]))

def _get_all_query_args(self, params, initial_query_string=''):
    pairs = []

    if initial_query_string:
        pairs.append(initial_query_string)

    for key, value in sorted(params.items(), key=lambda x: x[0]):
        if value is None:
            continue
        key = key.replace('_', '-')
        if key == 'maxkeys':
            key = 'max-keys'
        if not isinstance(value, six.string_types + (six.binary_type,)):
            value = six.text_type(value)
        if not isinstance(value, six.binary_type):
            value = value.encode('utf-8')
        if value:
            pairs.append(u'%s=%s' % (
                urllib.parse.quote(key),
                urllib.parse.quote(value)
            ))

    return '&'.join(pairs)
